private void notifyInterestedUsers(User seller, ProductSize productSize, int bidPrice) {
    ProductColor productColor = productSize.getProductColor();
    String message = String.format("관심 상품 [%s] 사이즈 %s에 새 판매 입찰이 등록되었습니다. 판매 희망가 %,d원",
